package com.example.rokidgeminisecretary;
public final class LocalShareAddressPolicyTest {static int n;static void ok(boolean v,String s){n++;if(!v)throw new AssertionError(s);}public static void main(String[] args){LocalShareAddressPolicy.Choice c=new LocalShareAddressPolicy.Choice();c.offer("100.79.53.91","rmnet_data0",false,false,false,true);c.offer("192.168.0.10","wlan0",true,false,false,false);ok(c.address.equals("192.168.0.10"),"actual cellular-first regression");for(String cell:new String[]{"rmnet_data0","v4-rmnet_data0","ccmni0","pdp_ip0","wwan0","clat4","tun0","ppp0","dummy0"})ok(LocalShareAddressPolicy.priority(cell,false,false,false)<0,"reject non-local interface "+cell);for(String ip:new String[]{"192.168.0.10","10.0.0.4","172.20.10.1"}){c=new LocalShareAddressPolicy.Choice();c.offer("100.79.53.91","rmnet_data0",false,false,false,true);c.offer(ip,"wlan0",true,false,false,false);ok(c.address.equals(ip),"Wi-Fi priority "+ip);}c=new LocalShareAddressPolicy.Choice();c.offer("100.79.53.91","rmnet_data0",false,false,false,true);ok(c.address.isEmpty(),"no cellular fallback");c.offer("192.168.43.1","ap0",false,false,false,false);ok(c.address.equals("192.168.43.1"),"hotspot fallback");c=new LocalShareAddressPolicy.Choice();c.offer("10.1.1.1","tun0",true,false,true,true);c.offer("192.168.1.20","eth0",false,true,false,true);ok(c.address.equals("192.168.1.20"),"Ethernet and VPN priority");for(String ip:new String[]{"","スマホのWi-Fi IP","127.0.0.1","0.0.0.0","169.254.2.1","224.0.0.1","256.1.1.1","1.2.3","host.local","1.2.3.4:8766"})ok(!LocalShareAddressPolicy.valid(ip),"reject invalid "+ip);for(String name:new String[]{"swlan0","ap0","ap_br_swlan0","softap0"}){c=new LocalShareAddressPolicy.Choice();c.offer("192.168.0.10","wlan0",true,false,false,true);c.offer("192.168.146.1",name,false,false,false,false);ok(c.address.equals("192.168.146.1"),"hotspot priority over concurrent Wi-Fi "+name);}System.out.println("PASS "+n+" LAN address selection checks");}}
